// toApiUserDTO 把 service.ApiUser 转 ApiUser DTO。
func toApiUserDTO(u authservice.ApiUser) *authpb.ApiUser {
	return &authpb.ApiUser{
		Id:              u.ID,
		Username:        u.Username,
		Role:            u.Role,
		AuthSource:      u.AuthSource,
		DefaultPromptId: u.DefaultPromptID,
		AutoEvolution:   u.AutoEvolution,
	}
}

// writeAuthError 把 service 错误映射到 HTTP 状态。
func writeAuthError(c *app.RequestContext, err error) {
	switch {
	case errors.Is(err, authservice.ErrInvalidCredentials):
		c.JSON(consts.StatusUnauthorized, map[string]string{"error": err.Error()})
	case errors.Is(err, authservice.ErrAccountDisabled):
		c.JSON(consts.StatusForbidden, map[string]string{"error": err.Error()})
	case errors.Is(err, authservice.ErrPasswordNotSet):
		c.JSON(consts.StatusBadRequest, map[string]string{"error": err.Error()})
	default:
		c.JSON(consts.StatusInternalServerError, map[string]string{"error": err.Error()})
	}
}
